  )
}

function AgentRow({
  agent, deleting, onDelete, onCopy, onMove,
}: {
  agent: UnifiedAgent; deleting: boolean; onDelete: (a: UnifiedAgent) => void; onCopy: (a: UnifiedAgent) => void; onMove: (a: UnifiedAgent) => void
}) {
  const editLink = agent.scope === 'global' ? `/global/agents/${agent.filename}` : `/projects/${agent.projectId}/agents/${agent.filename}`

  return (
    <div className="group flex items-center justify-between bg-surface border border-border rounded-lg px-3 py-2.5 hover:border-accent/20 transition-all">
      <Link to={editLink} className="flex items-center gap-3 flex-1 min-w-0">
        <AgentIcon name={agent.name} uid={`${agent.scope}-${agent.filename}`} size={36} global={agent.scope === 'global'} />
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <span className="text-sm font-semibold group-hover:text-accent-hover transition-colors truncate">{agent.name}</span>
            <AgentCategoryBadge category={agent.frontmatter?.category as string} />
            <ScopeBadge agent={agent} />
          </div>
          <p className="text-[11px] text-text-muted truncate mt-0.5">{agent.description}</p>
        </div>
        <div className="flex items-center gap-2 shrink-0">
