// Derive a 1-line tagline from a description: first sentence, soft-capped at 80 chars.
function deriveTagline(description: string): string {
  const text = (description || '').trim().replace(/\s+/g, ' ')
  if (!text) return ''
  // First sentence: first '.', '!', or '?' that ends a word.
  const match = text.match(/^[^.!?]+[.!?]/)
  let s = match ? match[0].trim() : text
  if (s.length > 80) {
    s = s.slice(0, 80).replace(/\s+\S*$/, '') + '…'
  } else if (!match && text.length > 80) {
    s = text.slice(0, 80).replace(/\s+\S*$/, '') + '…'
  }
  return s.replace(/[.!?]$/, '')
}

function AgentRow({
  agent, deleting, onDelete, onCopy, onMove,
}: {
  agent: UnifiedAgent; deleting: boolean; onDelete: (a: UnifiedAgent) => void; onCopy: (a: UnifiedAgent) => void; onMove: (a: UnifiedAgent) => void
}) {
  const editLink = agent.scope === 'global' ? `/global/agents/${agent.filename}` : `/projects/${agent.projectId}/agents/${agent.filename}`
  const tagline = deriveTagline(agent.description)

  return (
    <div className="group flex items-center justify-between bg-surface border border-border rounded-lg px-3 py-2.5 hover:border-accent/20 transition-all">
      <Link to={editLink} className="flex items-center gap-3 flex-1 min-w-0">
        <AgentIcon name={agent.name} uid={`${agent.scope}-${agent.filename}`} size={36} global={agent.scope === 'global'} />
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-sm font-semibold group-hover:text-accent-hover transition-colors truncate">{agent.name}</span>
            {agent.org?.isLeader && <LeaderBadge />}
            <LevelBadge org={agent.org} />
            <ExperienceBadge years={agent.org?.yearsOfExperience ?? null} />
            <ScopeBadge agent={agent} />
          </div>
          <p className="text-[11px] text-text-muted truncate mt-0.5" title={agent.description}>{tagline}</p>
        </div>
        <div className="flex items-center gap-2 shrink-0">
          <span className="text-[10px] font-mono bg-surface-2 px-1.5 py-0.5 rounded text-text-muted">{agent.model || 'sonnet'}</span>
          <span className="text-[10px] text-text-muted flex items-center gap-1"><Clock className="w-3 h-3" />{new Date(agent.updatedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}</span>
        </div>
      </Link>
      <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity shrink-0 ml-2">
        <button onClick={(e) => { e.stopPropagation(); onCopy(agent) }} title="Copy" className="p-1.5 rounded-md text-text-muted hover:text-accent hover:bg-accent-muted"><Copy className="w-3 h-3" /></button>
